    const count = usedAnchors.get(base) ?? 0;
    usedAnchors.set(base, count + 1);
    const anchor = count === 0 ? base : `${base}-${count}`;

    headings.push({
      level,
      display: options.stripFormattingInToc ? plainText : displayText,
