  }

  for (const match of text.matchAll(blockMathRegex)) {
    ranges.push({startIndex: match.index, endIndex: match.index + match[0].length});
  }

  return ranges;
}

function isInRanges(ranges: Position[], index: number): boolean {
  return ranges.some((range) => index >= range.startIndex && index < range.endIndex);
}

/**
 * Checks if the given heading text should be excluded from the TOC based on the exclude list.
 * @param {string} headingText The heading text to check
 * @param {string[]} excludeHeadings The list of excluded headings (literals or `/.../` regexes)
 * @return {boolean} Whether the heading should be excluded
 */
function isHeadingExcluded(headingText: string, excludeHeadings: string[]): boolean {
  for (const entry of excludeHeadings) {
    if (entry.length >= 2 && entry.startsWith('/') && entry.endsWith('/')) {
      const pattern = entry.slice(1, -1);
      if (pattern !== '' && new RegExp(pattern, 'i').test(headingText)) {
        return true;
      }
    } else if (headingText.toLowerCase() === entry.toLowerCase()) {
      return true;
    }
  }

  return false;
}

/**
 * Collects the headings that belong in the TOC in document order.
 * @param {string} text The full text of the document
 * @param {number} regionStart The start index of the TOC region
 * @param {number} regionEnd The end index of the TOC region (exclusive)
 * @param {AutoTocOptions} options The options to use when collecting the headings
 * @return {Array<TocHeading>} The headings to include in the TOC
 */
function collectHeadings(text: string, regionStart: number, regionEnd: number, options: AutoTocOptions): TocHeading[] {
  const ignoredRanges = getIgnoredRanges(text);
  const usedAnchors = new Map<string, number>();
  const headings: TocHeading[] = [];

  for (const match of text.matchAll(atxHeadingRegex)) {
    const headingStart = match.index;
    // headings in the TOC region itself are not part of the TOC
    if (headingStart >= regionStart && headingStart < regionEnd) {
      continue;
    }

    if (isInRanges(ignoredRanges, headingStart)) {
      continue;
    }

    const level = match[1].length;
    if (level < options.minLevel || level > options.maxLevel) {
      continue;
    }

    let headingText = (match[2] ?? '').replace(/\r$/, '').replace(closingHashesRegex, '');

    let explicitId: string | null = null;
    if (options.useExplicitIds) {
      const idMatch = explicitHeadingIdRegex.exec(headingText);
      if (idMatch !== null) {
        explicitId = idMatch[1];
        headingText = headingText.slice(0, headingText.length - idMatch[0].length);
      }
    }

    if (isHeadingExcluded(headingText, options.excludeHeadings)) {
      continue;
    }

    const textWithoutImages = headingText
        .replace(wikiImageEmbedRegex, '')
        .replace(genericImageEmbedRegex, '');
    const displayText = resolveLinksToDisplayText(textWithoutImages);
    const plainText = stripFormatting(displayText);

    const baseAnchor = explicitId !== null ? explicitId : buildAnchorBase(plainText);
    const anchorCount = usedAnchors.get(baseAnchor) ?? 0;
    usedAnchors.set(baseAnchor, anchorCount + 1);
    const anchor = anchorCount === 0 ? baseAnchor : `${baseAnchor}-${anchorCount}`;

    headings.push({
      level,
      displayText: options.stripFormattingInToc ? plainText : displayText,
      anchor,
    });
  }

  return headings;
}

/**
 * Turns the collected headings into TOC list item lines.
 * @param {Array<TocHeading>} headings The headings to build the list items from
 * @param {AutoTocOptions} options The options to use when building the list items
 * @return {string[]} The TOC list item lines
 */
function buildTocItems(headings: TocHeading[], options: AutoTocOptions): string[] {
  const items: string[] = [];
  let orderedItemNumber = 0;

  for (const heading of headings) {
    const indent = ' '.repeat((heading.level - options.minLevel) * options.indentSize);
    let marker: string;
    if (options.listStyle === 'number') {
      if (options.orderedListStyle === 'increment') {
        orderedItemNumber++;
        marker = `${orderedItemNumber}.`;
      } else {
        marker = '1.';
      }
    } else {
      marker = options.bulletMarker;
    }

    items.push(`${indent}${marker} [${heading.displayText}](#${heading.anchor})`);
  }

  return items;
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({
      nameKey: 'rules.auto-toc.name',
      descriptionKey: 'rules.auto-toc.description',
      type: RuleType.CONTENT,
    });
  }
  get OptionsClass(): new () => AutoTocOptions {
    return AutoTocOptions;
  }
  apply(text: string, options: AutoTocOptions): string {
    options = Object.assign(new AutoTocOptions(), options);

    const startMatch = tocStartMarkerRegex.exec(text);
    if (startMatch === null) {
      return text;
    }

    const startMarker = startMatch[0];
    const startMarkerIndex = startMatch.index;
    const startMarkerEnd = startMarkerIndex + startMarker.length;

    // find the first end marker after the start marker; if there is none, one will be inserted right after the start marker
    const endMatch = tocEndMarkerRegex.exec(text.slice(startMarkerEnd));
    let endMarker = tocEndMarker;
    let endMarkerEnd = startMarkerEnd;
    if (endMatch !== null) {
      const endMarkerIndex = startMarkerEnd + endMatch.index;
      endMarker = endMatch[0];
      endMarkerEnd = endMarkerIndex + endMatch[0].length;
    }

    const headings = collectHeadings(text, startMarkerIndex, endMarkerEnd, options);
    const items = buildTocItems(headings, options);

    const regionLines: string[] = [startMarker];
    if (options.title !== '') {
      regionLines.push('', options.title);
    }

    if (items.length > 0) {
      regionLines.push('', ...items);
    }

    regionLines.push('', endMarker);

    let prefix = text.slice(0, startMarkerIndex);
    if (prefix !== '' && !prefix.endsWith('\n')) {
      prefix += '\n';
