type Position = {startIndex: number, endIndex: number};

type TocHeading = {
  level: number,
  displayText: string,
  anchor: string,
};

/**
 * Removes inline formatting (code, bold, italics, strikethrough, and highlight) from the given text.
 * @param {string} text The text to remove formatting from
 * @return {string} The text without the inline formatting markers
 */
function stripFormatting(text: string): string {
  return text
      .replace(/`([^`]*)`/g, '$1')
      .replace(/\*\*([^*]*)\*\*/g, '$1')
      .replace(/__([^_]*)__/g, '$1')
      .replace(/\*([^*]*)\*/g, '$1')
      .replace(/_([^_]*)_/g, '$1')
      .replace(/~~([^~]*)~~/g, '$1')
      .replace(/==([^=]*)==/g, '$1');
}

/**
 * Resolves wiki links and markdown links to their display text.
 * @param {string} text The text to resolve links in
 * @return {string} The text with links replaced by their display text
 */
function resolveLinksToDisplayText(text: string): string {
  let result = text.replaceAll(wikiLinkRegex, (_, _bang: string, $2: string, $3: string) => {
    if ($3 != null) {
      return $3.replace('|', '');
    }

    return $2;
  });

  result = result.replaceAll(genericLinkRegex, '$2');

  return result;
}

/**
 * Builds the base anchor for a heading from its text.
 * @param {string} text The (formatting free) text to build the anchor from
 * @return {string} The base anchor for the heading
 */
function buildAnchorBase(text: string): string {
  return text
      .toLowerCase()
      .replaceAll(' ', '-')
      .replace(/[^a-z0-9-]/g, '')
      .replace(/-{2,}/g, '-')
      .replace(/^-+/, '')
      .replace(/-+$/, '');
}

/**
 * Gets the ranges of the text that are part of YAML frontmatter, code blocks, or math blocks.
 * @param {string} text The text to get the ignored ranges from
 * @return {Array<Position>} The ranges that should be ignored
 */
function getIgnoredRanges(text: string): Position[] {
  const ranges: Position[] = [];

  const yamlMatch = yamlRegex.exec(text);
  if (yamlMatch !== null) {
    ranges.push({startIndex: 0, endIndex: yamlMatch[0].length});
  }

  for (const match of text.matchAll(codeBlockRegex)) {
    ranges.push({startIndex: match.index, endIndex: match.index + match[0].length});
  }

  for (const match of text.matchAll(blockMathRegex)) {
    ranges.push({startIndex: match.index, endIndex: match.index + match[0].length});
  }

  return ranges;
}

function isInRanges(ranges: Position[], index: number): boolean {
  return ranges.some((range) => index >= range.startIndex && index < range.endIndex);
}

/**
 * Checks if the given heading text should be excluded from the TOC based on the exclude list.
 * @param {string} headingText The heading text to check
 * @param {string[]} excludeHeadings The list of excluded headings (literals or `/.../` regexes)
 * @return {boolean} Whether the heading should be excluded
 */
function isHeadingExcluded(headingText: string, excludeHeadings: string[]): boolean {
  for (const entry of excludeHeadings) {
    if (entry.length >= 2 && entry.startsWith('/') && entry.endsWith('/')) {
      const pattern = entry.slice(1, -1);
      if (pattern !== '' && new RegExp(pattern, 'i').test(headingText)) {
        return true;
      }
    } else if (headingText.toLowerCase() === entry.toLowerCase()) {
      return true;
    }
  }

  return false;
}

/**
 * Collects the headings that belong in the TOC in document order.
 * @param {string} text The full text of the document
 * @param {number} regionStart The start index of the TOC region
 * @param {number} regionEnd The end index of the TOC region (exclusive)
 * @param {number} minLevel The minimum heading level to include
 * @param {number} maxLevel The maximum heading level to include
 * @param {boolean} useExplicitIds Whether a trailing `{#id}` on a heading provides its anchor
 * @param {boolean} stripFormatting Whether formatting should be removed from the entry text
 * @param {string[]} excludeHeadings The headings to exclude from the TOC
 * @return {Array<TocHeading>} The headings to include in the TOC
 */
function collectHeadings(text: string, regionStart: number, regionEnd: number, minLevel: number, maxLevel: number,
    useExplicitIds: boolean, stripFormatting: boolean, excludeHeadings: string[]): TocHeading[] {
  const ignoredRanges = getIgnoredRanges(text);
  const usedAnchors = new Map<string, number>();
  const headings: TocHeading[] = [];

  for (const match of text.matchAll(atxHeadingRegex)) {
    const headingStart = match.index;
    // headings in the TOC region itself are not part of the TOC
    if (headingStart >= regionStart && headingStart < regionEnd) {
      continue;
    }

    if (isInRanges(ignoredRanges, headingStart)) {
      continue;
    }

    const level = match[1].length;
    if (level < minLevel || level > maxLevel) {
      continue;
    }

    let headingText = (match[2] ?? '').replace(/\r$/, '').replace(closingHashesRegex, '');

    let explicitId: string | null = null;
    if (useExplicitIds) {
      const idMatch = explicitHeadingIdRegex.exec(headingText);
      if (idMatch !== null) {
        explicitId = idMatch[1];
        headingText = headingText.slice(0, headingText.length - idMatch[0].length);
      }
    }

    if (isHeadingExcluded(headingText, excludeHeadings)) {
      continue;
    }

    const textWithoutImages = headingText
        .replace(wikiImageEmbedRegex, '')
        .replace(genericImageEmbedRegex, '');
    const displayText = resolveLinksToDisplayText(textWithoutImages);
    const plainText = stripFormatting(displayText);

    const baseAnchor = explicitId !== null ? explicitId : buildAnchorBase(plainText);
    const anchorCount = usedAnchors.get(baseAnchor) ?? 0;
    usedAnchors.set(baseAnchor, anchorCount + 1);
    const anchor = anchorCount === 0 ? baseAnchor : `${baseAnchor}-${anchorCount}`;

    headings.push({
      level,
      displayText: stripFormatting ? plainText : displayText,
      anchor,
    });
