 * Turns the collected headings into TOC list item lines.
 * @param {Array<TocHeading>} headings The headings to build the list items from
 * @param {string} listStyle Whether the TOC uses a bullet or a numbered list
 * @param {string} bulletMarker The marker to use for bullet list items
 * @param {string} orderedListStyle How to number the ordered list items
 * @param {number} indentSize The number of spaces to indent for each heading level above the minimum
 * @param {number} minLevel The minimum heading level included in the TOC
 * @return {string[]} The TOC list item lines
 */
function buildTocItems(headings: TocHeading[], listStyle: string, bulletMarker: string, orderedListStyle: string,
    indentSize: number, minLevel: number): string[] {
  const items: string[] = [];
  let orderedItemNumber = 0;

  for (const heading of headings) {
    const indent = ' '.repeat((heading.level - minLevel) * indentSize);
    let marker: string;
    if (listStyle === 'number') {
      if (orderedListStyle === 'increment') {
