import {Options, RuleType} from '../rules';
import RuleBuilder, {
  BooleanOptionBuilder,
  DropdownOptionBuilder,
  ExampleBuilder,
  NumberOptionBuilder,
  OptionBuilderBase,
  TextAreaOptionBuilder,
  TextOptionBuilder,
} from './rule-builder';
import dedent from 'ts-dedent';
import {codeBlockRegex, genericLinkRegex, wikiLinkRegex, yamlRegex} from '../utils/regex';

const tocStartMarkerRegex = /<!--\s*toc\s*-->/i;
const tocEndMarkerRegex = /<!--\s*\/\s*toc\s*-->/i;
const tocEndMarker = '<!-- /toc -->';
// ATX headings only: up to 3 leading spaces, 1-6 hashes, then a space (or end of line) and the heading text
const atxHeadingRegex = /^ {0,3}(#{1,6})(?:[ \t]+(.*))?[ \t]*$/gm;
// optional closing sequence of hashes at the end of a heading
const closingHashesRegex = /[ \t]+#+[ \t]*$/;
// Obsidian explicit heading id: `{#id}` at the end of the heading
const explicitHeadingIdRegex = /[ \t]*\{#([^\s{}]+)\}[ \t]*$/;
const wikiImageEmbedRegex = /!\[\[[^\]\n]*\]\]/g;
const genericImageEmbedRegex = /!\[[^\]\n]*\]\([^()\n]*\)/g;
// block math delimited by `$$` on their own lines
const blockMathRegex = /^ {0,3}\$\$[\s\S]*?\$\$/gm;

class AutoTocOptions implements Options {
  listStyle?: 'bullet' | 'number' = 'bullet';
  bulletMarker?: string = '-';
  orderedListStyle?: 'always-one' | 'increment' = 'always-one';
  indentSize?: Number = 2;
  minLevel?: Number = 2;
  maxLevel?: Number = 6;
  title?: string = '';
  useExplicitIds?: boolean = false;
  stripFormattingInToc?: boolean = false;
  excludeHeadings?: string[] = [];
}

type Position = {startIndex: number, endIndex: number};

type TocHeading = {
  level: number,
  displayText: string,
  anchor: string,
};

/**
 * Removes inline formatting (code, bold, italics, strikethrough, and highlight) from the given text.
 * @param {string} text The text to remove formatting from
 * @return {string} The text without the inline formatting markers
 */
function stripFormatting(text: string): string {
  return text
      .replace(/`([^`]*)`/g, '$1')
      .replace(/\*\*([^*]*)\*\*/g, '$1')
      .replace(/__([^_]*)__/g, '$1')
      .replace(/\*([^*]*)\*/g, '$1')
      .replace(/_([^_]*)_/g, '$1')
      .replace(/~~([^~]*)~~/g, '$1')
      .replace(/==([^=]*)==/g, '$1');
}

/**
 * Resolves wiki links and markdown links to their display text.
 * @param {string} text The text to resolve links in
 * @return {string} The text with links replaced by their display text
 */
function resolveLinksToDisplayText(text: string): string {
  let result = text.replaceAll(wikiLinkRegex, (_, _bang: string, $2: string, $3: string) => {
    if ($3 != null) {
      return $3.replace('|', '');
    }

    return $2;
  });

  result = result.replaceAll(genericLinkRegex, '$2');

  return result;
}

/**
 * Builds the base anchor for a heading from its text.
 * @param {string} text The (formatting free) text to build the anchor from
 * @return {string} The base anchor for the heading
 */
function buildAnchorBase(text: string): string {
  return text
      .toLowerCase()
      .replaceAll(' ', '-')
      .replace(/[^a-z0-9-]/g, '')
      .replace(/-{2,}/g, '-')
      .replace(/^-+/, '')
      .replace(/-+$/, '');
}

/**
 * Gets the ranges of the text that are part of YAML frontmatter, code blocks, or math blocks.
 * @param {string} text The text to get the ignored ranges from
 * @return {Array<Position>} The ranges that should be ignored
 */
function getIgnoredRanges(text: string): Position[] {
  const ranges: Position[] = [];

  const yamlMatch = yamlRegex.exec(text);
  if (yamlMatch !== null) {
    ranges.push({startIndex: 0, endIndex: yamlMatch[0].length});
  }
